script:
country_event = {
	id = crisis.17
	hide_window = yes
	fire_only_once = yes

	mean_time_to_happen = {
		months = 30
	}

	trigger = {
		has_global_flag = prethoryn_transmission
	}

	immediate = {
		set_crisis_sound = swarm_crisis_ambient_stage_1
		set_crisis_stage_1 = yes
		awaken_guardians_of_the_galaxy = yes

		remove_global_flag = prethoryn_approaching_rim
		set_global_flag = prethoryn_arrival
		observer_event = { id = observer.29 }
		every_country = {
			limit = { is_country_type = default }
			country_event = { id = crisis.18 }
		}
		random_rim_system = {
			limit = { has_star_flag = swarm_invasion_target_1 }
			random_system_planet = {
				create_species = {
					name = "NAME_Prethoryn"
					class = SWARM
					namelist = Prethoryn
					portrait = random
					traits = random
					immortal = yes

					effect = { save_event_target_as = prethoryn_species }
				}
				create_country = {
					name = "NAME_Prethoryn_Scourge"
					type = "swarm"
					species = event_target:prethoryn_species
					name_list = "Prethoryn"
					flag = {
						icon= {
							category = "special"
							file = "the_swarm.dds"
						}
						background= {
							category = "backgrounds"
							file = "new_dawn.dds"
						}
						colors={
							"orange"
							"grey"
							"null"
							"null"
						}
					}
					effect = {
						save_event_target_as = prethoryn
						save_event_target_as = prethoryn_vgrd
						create_ship_design = { design = "NAME_Swarm_Transport" }
						add_ship_design = last_created_design
						create_ship_design = { design = "NAME_Swarm_Colonizer" }
						add_ship_design = last_created_design
						create_ship_design = { design = "NAME_Swarm_Constructor" }
						add_ship_design = last_created_design
						create_ship_design = { design = "NAME_Swarm_Starbase" }
						add_ship_design = last_created_design
					}
				}
				solar_system = {
					if = {
						limit = {
							any_fleet_in_system = {
								is_ship_class = shipclass_starbase
							}
						}
						random_fleet_in_system = {
							limit = {
								any_controlled_ship = {
									is_ship_class = shipclass_starbase
								}
							}
							destroy_fleet = this
						}
					}
					create_starbase = {
						size = starbase_swarm
						owner = event_target:prethoryn_vgrd
					}
					star = {
						create_ambient_object = {
							type = "swarm_1"
							location = this
						}
						last_created_ambient_object = {
							set_ambient_object_flag = swarm_system_effect
							set_location = {
								target = prev
								distance = 0
								angle = random
							}
						}
					}
				}
				every_country = {
					limit = {
						OR = {
							is_country_type = default
							is_country_type = fallen_empire
							is_country_type = awakened_fallen_empire
						}
					}
					establish_communications_no_message = event_target:prethoryn
					add_opinion_modifier = {
						who = event_target:prethoryn
						modifier = opinion_swarm
					}
					event_target:prethoryn = {
						add_opinion_modifier = {
							who = PREV
							modifier = opinion_prey
						}
					}
					if = {
						limit = { has_technology = tech_gravity_wells }
						country_event = {
							id = grand_archive.7220
							days = 30
						}
					}
				}
				event_target:prethoryn = {

					### FIRST SYSTEM

					swarm_vanguard = yes
					swarm_vanguard = yes
					if = {
						limit = {
							is_difficulty >= 3
						}
						swarm_vanguard = yes
					}
					if = {
						limit = {
							is_difficulty >= 5
						}
						swarm_vanguard = yes
					}
					if = {
						limit = {
							is_difficulty >= 6
						}
						swarm_vanguard = yes
					}


					# Constructor
					create_fleet = {
						name = "NAME_Prethoryn_Constructor"
						effect = {
							set_owner = PREV
							create_ship = {
								name = random
								design = "NAME_Swarm_Constructor"
								graphical_culture = "swarm_01"
							}
							set_location = {
								target = PREVPREV
								distance = 10
								angle = random
							}
						}
					}
				}
			}

			### SECOND SYSTEM
			random_system = {
				limit = {
					distance = {
						source = PREV
						max_distance <= 60
						min_distance >= 5
					}
				}
				set_star_flag = swarm_invasion_target_2
				random_system_planet = {
					event_target:prethoryn = {

						swarm_vanguard = yes
						swarm_vanguard = yes
						if = {
							limit = {
								is_difficulty >= 3
							}
							swarm_vanguard = yes
						}
						if = {
							limit = {
								is_difficulty >= 5
							}
							swarm_vanguard = yes
						}
						if = {
							limit = {
								is_difficulty >= 6
							}
							swarm_vanguard = yes
						}

						# Constructor
						create_fleet = {
							name = "NAME_Prethoryn_Constructor"
							effect = {
								set_owner = PREV
								create_ship = {
									name = random
									design = "NAME_Swarm_Constructor"
									graphical_culture = "swarm_01"
								}
								set_location = {
									target = PREVPREV
									distance = 10
									angle = random
								}
							}
						}
					}
				}
			}

			### THIRD SYSTEM
			random_system = {
				limit = {
					distance = {
						source = PREV
						max_distance <= 60
						min_distance >= 5
					}
					NOR = {
						has_star_flag = swarm_invasion_target_1
						has_star_flag = swarm_invasion_target_2
					}
				}
				set_star_flag = swarm_invasion_target_3
				random_system_planet = {
					event_target:prethoryn = {

						swarm_vanguard = yes
						swarm_vanguard = yes
						if = {
							limit = {
								is_difficulty >= 3
							}
							swarm_vanguard = yes
						}
						if = {
							limit = {
								is_difficulty >= 5
							}
							swarm_vanguard = yes
						}
						if = {
							limit = {
								is_difficulty >= 6
							}
							swarm_vanguard = yes
						}

						# Constructor
						create_fleet = {
							name = "NAME_Prethoryn_Constructor"
							effect = {
								set_owner = PREV
								create_ship = {
									name = random
									design = "NAME_Swarm_Constructor"
									graphical_culture = "swarm_01"
								}
								set_location = {
									target = PREVPREV
									distance = 10
									angle = random
								}
							}
						}
					}
				}
			}

			### FOURTH SYSTEM
			random_system = {
				limit = {
					distance = {
						source = PREV
						max_distance <= 60
						min_distance >= 5
					}
					NOR = {
						has_star_flag = swarm_invasion_target_1
						has_star_flag = swarm_invasion_target_2
						has_star_flag = swarm_invasion_target_3
					}
				}
				set_star_flag = swarm_invasion_target_4
				random_system_planet = {
					event_target:prethoryn = {

						swarm_vanguard = yes
						swarm_vanguard = yes
						if = {
							limit = {
								is_difficulty >= 3
							}
							swarm_vanguard = yes
						}
						if = {
							limit = {
								is_difficulty >= 5
							}
							swarm_vanguard = yes
						}
						if = {
							limit = {
								is_difficulty >= 6
							}
							swarm_vanguard = yes
						}

						# Constructor
						create_fleet = {
							name = "NAME_Prethoryn_Constructor"
							effect = {
								set_owner = PREV
								create_ship = {
									name = random
									design = "NAME_Swarm_Constructor"
									graphical_culture = "swarm_01"
								}
								set_location = {
									target = PREVPREV
									distance = 10
									angle = random
								}
							}
						}
					}
				}
			}
		}
		random_country = {
			limit = { is_country_type = global_event }
			country_event = { id = crisis.19 days = 400 random = 200 }
		}
	}
	after = {
		every_playable_country = {
			country_event = { id = timeline.70 } # Timeline Prethoryn Scourge
		}
	}
}

