carrier_event = {
	id = crisis.202
	hide_window = yes

	is_triggered_only = yes

	trigger = {
		pop_amount <= 100
		exists = controller
		controller = { is_country_type = "swarm" }
	}

	immediate = {
		from = { save_event_target_as = swarm }
		if = {
			limit = {
				is_artificial = no
			}
			change_pc = pc_infested
			set_owner = event_target:swarm
			carrier_event = { id = crisis.215 }
		}
		else_if = {
			# Habitable Ring Worlds can't be infested...
			# they are destroyed instead
			limit = {
				is_ringworld = yes
			}
			destroy_colony = yes
			change_pc = pc_ringworld_habitable_damaged
			reset_planet = yes
		}
		else_if = {
			limit = { is_planet_class = pc_habitat }
			spawn_habitat_cracker_effect = yes
		}

		solar_system = {
			if = { # Build starbase if no other colonies are left and no hostile fleet is in the system
				limit = {
					NOR = {
						exists = starbase
						any_system_planet = {
							has_owner = yes
							owner = {
								NOT = { is_same_value = event_target:swarm }
							}
						}
						any_fleet_in_system = {
							owner = { is_hostile = event_target:swarm }
						}
					}
				}
				create_starbase = {
					size = starbase_swarm
					owner = event_target:swarm
				}
				if = {
					limit = {
						NOT = {
							any_system_ambient_object = { has_ambient_object_flag = swarm_system_effect }
						}
					}
					star = {
						create_ambient_object = {
							type = "swarm_1"
							location = this
						}
						last_created_ambient_object = {
							set_ambient_object_flag = swarm_system_effect
							set_location = {
								target = prev
								distance = 0
								angle = random
							}
						}
					}
				}
			}
		}
	}
}

