script:
country_event = {
	id = crisis.266
	hide_window = yes

	is_triggered_only = yes

	immediate = {
		if = {
			limit = {
				exists = event_target:starbase_system
				event_target:starbase_system = {
					any_system_planet = {
						owner = { is_same_value = root }
					}
					NOT = {
						any_fleet_in_system = {
							owner = { is_hostile = root }
						}
					}
				}
			}
			event_target:starbase_system = {
				solar_system = {
					create_starbase = {
						size = starbase_swarm
						owner = root
					}
					star = {
						create_ambient_object = {
							type = "swarm_1"
							location = this
						}
						last_created_ambient_object = {
							set_ambient_object_flag = swarm_system_effect
							set_location = {
								target = prev
								distance = 0
								angle = random
							}
						}
					}
					every_system_planet = {
						limit = { has_orbital_station = yes }
						orbital_station = { dismantle = yes }
					}
				}
			}
		}
		else_if = {
			limit = {
				exists = event_target:starbase_system
				event_target:starbase_system = {
					any_system_planet = {
						owner = { is_same_value = root }
					}
				}
			}
			country_event = { id = crisis.266 days = 30 } # Retry until hostile fleets leave the system
		}
	}
}

